class NotesViewModel(private val repository: NoteRepository) : ViewModel() {
    val notes: StateFlow<List<Note>> = repository.observeNotes()
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), emptyList())

    fun onDelete(id: Long) { viewModelScope.launch { repository.delete(id) } }
}

@Composable
fun NotesScreen(viewModel: NotesViewModel) {
    val notes by viewModel.notes.collectAsStateWithLifecycle()   // View observes state
    NotesList(notes, onDelete = viewModel::onDelete)              // and forwards events
}

@Composable
fun CounterScreen(viewModel: CounterViewModel) {
    val state by viewModel.state.collectAsStateWithLifecycle()

    CounterContent(
        count = state.count,                 // state flows down
        onIncrement = viewModel::increment   // events flow up
    )
}

@Composable
fun CounterContent(count: Int, onIncrement: () -> Unit) {
    Button(onClick = onIncrement) { Text("Clicked $count times") }   // stateless and easy to preview
}

data class CounterState(val count: Int = 0, val loading: Boolean = false)

sealed interface CounterIntent {
    data object Increment : CounterIntent
    data object Reset : CounterIntent
}

fun reduce(state: CounterState, intent: CounterIntent): CounterState = when (intent) {
    CounterIntent.Increment -> state.copy(count = state.count + 1)
    CounterIntent.Reset -> state.copy(count = 0)
}

class CounterViewModel : ViewModel() {
    private val _state = MutableStateFlow(CounterState())
    val state = _state.asStateFlow()

    fun onIntent(intent: CounterIntent) = _state.update { reduce(it, intent) }
}

data class HomeState(
    val user: User? = null,
    val orders: List<Order> = emptyList(),
    val isRefreshing: Boolean = false
)

class HomeViewModel(users: UserRepository, orders: OrderRepository) : ViewModel() {
    private val refreshing = MutableStateFlow(false)

    val state: StateFlow<HomeState> = combine(
        users.observeUser(), orders.observeOrders(), refreshing
    ) { user, orderList, isRefreshing ->
        HomeState(user, orderList, isRefreshing)          // one consistent snapshot
    }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), HomeState())
}

@Stable
class SearchBarState(initialQuery: String = "") {
    var query by mutableStateOf(initialQuery)
        private set
    var expanded by mutableStateOf(false)
        private set

    fun onQueryChange(value: String) { query = value }
    fun onExpandedChange(value: Boolean) { expanded = value }
}

@Composable
fun rememberSearchBarState() = remember { SearchBarState() }   // lives as long as the composition

// Data layer: library exceptions -> domain errors
sealed interface DomainError {
    data object NoConnection : DomainError
    data object NotFound : DomainError
    data class Unknown(val cause: Throwable) : DomainError
}

fun Throwable.toDomainError(): DomainError = when {
    this is IOException -> DomainError.NoConnection
    this is HttpException && code() == 404 -> DomainError.NotFound
    else -> DomainError.Unknown(this)
}

// UI layer: domain error -> message (localizable)
@StringRes fun DomainError.message(): Int = when (this) {
    DomainError.NoConnection -> R.string.error_no_connection
    DomainError.NotFound -> R.string.error_not_found
    is DomainError.Unknown -> R.string.error_generic
}

data class LoginState(val loading: Boolean = false, val navigateToHome: Boolean = false)

class LoginViewModel(private val auth: AuthRepository) : ViewModel() {
    private val _state = MutableStateFlow(LoginState())
    val state = _state.asStateFlow()

    fun onLogin(user: String, password: String) = viewModelScope.launch {
        auth.login(user, password)
        _state.update { it.copy(navigateToHome = true) }
    }

    fun onNavigated() = _state.update { it.copy(navigateToHome = false) }
}

// UI
LaunchedEffect(state.navigateToHome) {
    if (state.navigateToHome) { navController.navigate(Home); viewModel.onNavigated() }
}

